import math
        import random
        import time

        LANGUAGE_WRAPPER = 'Consider the identities over the complex numbers that must hold for all real t. Determine how many positive integers n ≤ {n_max} simultaneously satisfy both:\n(1) (sin t + i cos t)^n = sin(n t) + i cos(n t), and\n(2) There exists a single real phase φ (independent of t) such that\n    (sin(t + π·{a1}/{b1}) + i cos(t + π·{a1}/{b1}))^n = sin(n t + φ) + i cos(n t + φ)\n    and\n    (sin(t + π·{a2}/{b2}) + i cos(t + π·{a2}/{b2}))^n = sin(n t + φ) + i cos(n t + φ).\nAnswer with the count of such n.'

        class _RNGShim:
    def __init__(self, seed: int):
        import random as _random
        self._seed = int(seed)
        self._r = _random.Random(self._seed)

    def random(self): return self._r.random()
    def uniform(self, a, b): return self._r.uniform(a, b)
    def randint(self, a, b): return self._r.randint(a, b)
    def randrange(self, *args): return self._r.randrange(*args)
    def choice(self, seq): return self._r.choice(seq)
    def choices(self, population, weights=None, cum_weights=None, k: int = 1):
        return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
    def sample(self, population, k: int): return self._r.sample(population, k)
    def shuffle(self, x):
        self._r.shuffle(x)
        return x
    def getrandbits(self, k: int): return self._r.getrandbits(k)

        import math

def generator(rng):
    # Helper to pick an integer in [1, 2*b - 1] with given parity
    def pick_num_with_parity(b, parity):
        choices = [x for x in range(1, 2*b) if (x % 2) == parity]
        return rng.choice(choices)

    while True:
        # Choose odd denominators
        b1 = rng.randrange(3, 51, 2)
        b2 = rng.randrange(3, 51, 2)
        # Ensure a1 and a2 have the same parity so that Delta is even (to help make M odd)
        parity = rng.choice([0, 1])
        a1 = pick_num_with_parity(b1, parity)
        a2 = pick_num_with_parity(b2, parity)
        # Compute Delta and M as derived in the verifier
        Delta = a1 * b2 - a2 * b1
        if Delta == 0:
            continue  # shifts equal -> trivial M=1; reject
        Nden = 2 * b1 * b2
        g = math.gcd(abs(Delta), Nden)
        M = Nden // g
        # Enforce non-trivial and odd M so that CRT with mod 4 has a solution
        if M <= 1 or (M % 2 == 0):
            continue
        # Find the smallest positive n0 solving n ≡ 0 (mod M) and n ≡ 1 (mod 4)
        n0 = None
        for k in range(1, 5):  # try k=1..4; since M odd, exactly one k works
            cand = M * k
            if cand % 4 == 1:
                n0 = cand
                break
        if n0 is None:
            continue  # should not happen if M is odd
        # Choose n_max to guarantee at least one solution and avoid trivial counts
        # Make sure we have multiple solutions reasonably often
        mult = rng.randint(1, 6)
        offset = rng.randrange(0, 4 * M)
        n_max = n0 + mult * 4 * M + offset
        # Sanity checks
        if n_max <= 0:
            continue
        # Return the instance
        return {
            'n_max': int(n_max),
            'a1': int(a1),
            'b1': int(b1),
            'a2': int(a2),
            'b2': int(b2)
        }

        import math

def verifier(assign):
    # Validate presence and types
    try:
        n_max = int(assign['n_max'])
        a1 = int(assign['a1'])
        b1 = int(assign['b1'])
        a2 = int(assign['a2'])
        b2 = int(assign['b2'])
    except Exception:
        # Missing or invalid types
        return (False, None)  # invalid assignment

    # Domain checks
    if n_max <= 0 or b1 <= 0 or b2 <= 0:
        # invalid domain
        return (False, None)
    if b1 % 2 == 0 or b2 % 2 == 0:
        # we require odd denominators for difficulty/consistency
        return (False, None)

    # Core derivation:
    # (1) (sin t + i cos t)^n = i^n e^{-i n t} must equal i e^{-i n t} => n ≡ 1 (mod 4).
    # (2) For a fixed φ to work for both shifted identities, we need
    #     i^n e^{-i n θ1} = i e^{-i φ} = i^n e^{-i n θ2}, where θj = π * aj/bj.
    #     Hence e^{-i n (θ1 - θ2)} = 1 => n(θ1 - θ2) is a multiple of 2π.
    #     With θ1 - θ2 = π * (a1/b1 - a2/b2) = π * Δ / (b1 b2), where Δ = a1 b2 - a2 b1,
    #     we require n * Δ / (b1 b2) ∈ 2Z, i.e., n is a multiple of M = (2 b1 b2) / gcd(|Δ|, 2 b1 b2).
    Delta = a1 * b2 - a2 * b1
    if Delta == 0:
        # trivial shift difference would make M=1; we disallow to enforce difficulty
        return (False, None)
    Nden = 2 * b1 * b2
    g = math.gcd(abs(Delta), Nden)
    M = Nden // g

    # Enforce non-trivial and odd M so CRT with mod 4 is solvable but not trivial
    if M <= 1:
        return (False, None)
    if M % 2 == 0:
        return (False, None)

    # Find the minimal positive solution n0 to the system: n ≡ 0 (mod M) and n ≡ 1 (mod 4).
    n0 = None
    for k in range(1, 5):
        cand = M * k
        if cand % 4 == 1:
            n0 = cand
            break
    if n0 is None:
        # Should not happen if M odd
        return (False, None)

    # Count solutions: n = n0 + t * lcm(4, M) = n0 + t * (4M) (since M is odd), for t ≥ 0.
    if n0 > n_max:
        answer = 0
    else:
        step = 4 * M
        answer = 1 + (n_max - n0) // step

    # As an additional difficulty guard, ensure the instance is not trivial like M=1 or answer == floor(n_max/4)
    if M == 1:
        return (False, None)

    return (True, int(answer))


        def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
            """Return dict with assignment/question/answer or raise RuntimeError."""
            start = time.time()
            attempts = 0
            while time.time() - start < timeout_seconds:
                attempts += 1
                rng = _RNGShim(seed + attempts)
                assignment = generator(rng)
                valid, answer = verifier(assignment)
                if valid:
                    question = LANGUAGE_WRAPPER.format(**assignment)
                    return {
                        "assignment": assignment,
                        "question": question,
                        "answer": answer,
                        "attempts": attempts,
                        "elapsed_seconds": time.time() - start,
                    }
            raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

